code.cpp:
class Solution {
public:
    vector<int> constructArray(int n, int k) {
        vector<int> res;
        res.reserve(n);
        int lo = 1, hi = n;
        for (int i = 0; i < k; i++) {
            if (i % 2 == 0)
                res.push_back(lo++);
            else
                res.push_back(hi--);
        }
        if (k % 2 == 0) {
            while (lo <= hi)
                res.push_back(hi--);
        } else {
            while (lo <= hi)
                res.push_back(lo++);
        }
        return res;
    }
};
